cat > /workspace/config.go << 'EOF'
package main

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"os/user"
	"path/filepath"
	"strings"
)

// Config holds direnv configuration
type Config struct {
	ConfigDir  string
	DataDir    string
	CacheDir   string
	BashPath   string
	SelfPath   string
	// ... other fields
}

// EnvState holds the current environment state
type EnvState struct {
	LoadedRC  string
	FoundRC   string
	EnvDiff   map[string]string
	EnvAdded  map[string]string
	EnvRemoved map[string]string
}

// GetConfig returns the configuration for direnv
func GetConfig(execPath string) *Config {
	cfg := &Config{
		SelfPath: execPath,
		BashPath: "/usr/bin/bash",
	}

	// Set config directory
	if configDir := os.Getenv("XDG_CONFIG_HOME"); configDir != "" {
		cfg.ConfigDir = filepath.Join(configDir, "direnv")
	} else {
		homeDir := os.Getenv("HOME")
		if homeDir == "" {
			u, _ := user.Current()
			if u != nil {
				homeDir = u.HomeDir
			}
		}
		cfg.ConfigDir = filepath.Join(homeDir, ".config", "direnv")
	}

	// Set data directory
	if dataDir := os.Getenv("XDG_DATA_HOME"); dataDir != "" {
		cfg.DataDir = filepath.Join(dataDir, "direnv")
	} else {
		homeDir := os.Getenv("HOME")
		if homeDir == "" {
			u, _ := user.Current()
			if u != nil {
				homeDir = u.HomeDir
			}
		}
		cfg.DataDir = filepath.Join(homeDir, ".local", "share", "direnv")
	}

	// Set cache directory
	if cacheDir := os.Getenv("XDG_CACHE_HOME"); cacheDir != "" {
		cfg.CacheDir = filepath.Join(cacheDir, "direnv")
	} else {
		homeDir := os.Getenv("HOME")
		if homeDir == "" {
			u, _ := user.Current()
			if u != nil {
				homeDir = u.HomeDir
			}
		}
		cfg.CacheDir = filepath.Join(homeDir, ".cache", "direnv")
	}

	// Create directories if they don't exist
	os.MkdirAll(cfg.ConfigDir, 0700)
	os.MkdirAll(cfg.DataDir, 0700)
	os.MkdirAll(cfg.CacheDir, 0700)

	return cfg
}

// GetAllowFile returns the path to the .envrc allowlist file
func (c *Config) GetAllowFile(rcPath string) (string, error) {
	// Hash the RC path
	absPath, err := filepath.Abs(rcPath)
	if err != nil {
		return "", err
	}

	hash := sha256.Sum256([]byte(absPath))
	hashStr := base64.RawURLEncoding.EncodeToString(hash[:])
	// Replace = with _ for filename safety
	hashStr = strings.ReplaceAll(hashStr, "=", "")

	return filepath.Join(c.DataDir, "allow", hashStr), nil
}

// IsAllowed checks if an .envrc file is allowed
func (c *Config) IsAllowed(rcPath string) bool {
	allowFile, err := c.GetAllowFile(rcPath)
	if err != nil {
		return false
	}

	// Check if the allow file exists
	_, err = os.Stat(allowFile)
	return err == nil
}

// Allow marks an .envrc file as allowed
func (c *Config) Allow(rcPath string) error {
	allowFile, err := c.GetAllowFile(rcPath)
	if err != nil {
		return err
	}

	// Create parent directory
	os.MkdirAll(filepath.Dir(allowFile), 0700)

	// Create the allow file - just an empty file with a hash of the content
	content, err := os.ReadFile(rcPath)
	if err != nil {
		return err
	}

	hash := sha256.Sum256(content)
	hashStr := base64.RawURLEncoding.EncodeToString(hash[:])

	// Store the hash in the allow file
	return os.WriteFile(allowFile, []byte(hashStr), 0600)
}

// IsAllowedAndValid checks if an .envrc file is allowed AND hasn't been modified
func (c *Config) IsAllowedAndValid(rcPath string) (bool, error) {
	allowFile, err := c.GetAllowFile(rcPath)
	if err != nil {
		return false, err
	}

	// Check if the allow file exists
	allowData, err := os.ReadFile(allowFile)
	if err != nil {
		return false, nil
	}

	// Check if content hash matches
	content, err := os.ReadFile(rcPath)
	if err != nil {
		return false, err
	}

	hash := sha256.Sum256(content)
	hashStr := base64.RawURLEncoding.EncodeToString(hash[:])

	return hashStr == string(allowData), nil
}

// Block removes the allow status of an .envrc file
func (c *Config) Block(rcPath string) error {
	allowFile, err := c.GetAllowFile(rcPath)
	if err != nil {
		return err
	}

	return os.Remove(allowFile)
}

// FindEnvrc searches for .envrc or .env files starting from the given directory
func FindEnvrc(dir string) (string, error) {
	for {
		// Check for .envrc first
		envrcPath := filepath.Join(dir, ".envrc")
		if _, err := os.Stat(envrcPath); err == nil {
			return envrcPath, nil
		}

		// Check for .env
		envPath := filepath.Join(dir, ".env")
		if _, err := os.Stat(envPath); err == nil {
			return envPath, nil
		}

		// Move to parent directory
		parent := filepath.Dir(dir)
		if parent == dir {
			// We've reached the root directory
			break
		}
		dir = parent
	}

	return "", fmt.Errorf("no .envrc or .env found")
}

// Dump marshals an environment state to JSON
func (s *EnvState) Dump() (string, error) {
	data, err := json.Marshal(s)
	return string(data), err
}

// Load unmarshals environment state from JSON
func LoadState(data string) (*EnvState, error) {
	s := &EnvState{}
	err := json.Unmarshal([]byte(data), s)
	return s, err
}
EOF

