func printDiffInfo(added, changed, removed map[string]string) {
	for k := range added {
		fmt.Fprintf(os.Stderr, "[0mdirenv: export +%s\n", k)
	}
	for k := range changed {
		fmt.Fprintf(os.Stderr, "[0mdirenv: export ~%s\n", k)
	}
	for k := range removed {
		fmt.Fprintf(os.Stderr, "[0mdirenv: export -%s\n", k)
	}
}

func addMetadata(output, rcPath, shell string) string {
	// Add direnv metadata at the end
	direnvDir := filepath.Dir(rcPath)
	if direnvDir == "." {
		direnvDir = "-"
	} else if !filepath.IsAbs(direnvDir) {
		abs, _ := filepath.Abs(direnvDir)
		direnvDir = "-" + abs
	}

	// Create watches data (compressed)
	watches := createWatches(rcPath)

	// Create diff data (compressed)
	diff := createDiff()

	switch shell {
	case "bash", "zsh":
		return fmt.Sprintf(
			"export DIRENV_FILE=%q;export DIRENV_WATCHES=%q;export DIRENV_DIFF=%q;export DIRENV_DIR=%q;%s",
			rcPath,
			watches,
			diff,
			direnvDir,
			output,
		)
	default:
		return output
	}
}

func createWatches(rcPath string) string {
	// Create a simple compressed representation
	data := []byte(`{"version": 1, "files": ["` + rcPath + `"]}`)
	return encodeGzipped(data)
}

func createDiff() string {
	data := []byte(`{"changes": []}`)
	return encodeGzipped(data)
}

func encodeGzipped(data []byte) string {
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	gz.Write(data)
	gz.Close()

	return "'" + base64.StdEncoding.EncodeToString(buf.Bytes()) + "'"
}

