	cmd := exec.Command(editor, rcPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()

	// Allow the file
	absPath, _ := filepath.Abs(rcPath)
	config.Allow(absPath)
