package main

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

const Version = "2.37.1"

var (
	config *Config
	execPath string
)

func init() {
	var err error
	execPath, err = os.Executable()
	if err != nil {
		execPath = os.Args[0]
	}
	config = GetConfig(execPath)
}

func main() {
	if len(os.Args) < 2 {
		printHelp()
		os.Exit(1)
	}

	command := os.Args[1]
	args := os.Args[2:]

	switch command {
	case "version":
		cmdVersion(args)
	case "help":
		cmdHelp(args)
	case "hook":
		cmdHook(args)
	case "export":
		cmdExport(args)
	case "allow", "permit", "grant":
		cmdAllow(args)
	case "block", "deny", "disallow", "revoke":
		cmdBlock(args)
	case "status":
		cmdStatus(args)
	case "exec":
		cmdExec(args)
	case "edit":
		cmdEdit(args)
	case "reload":
		cmdReload(args)
	case "stdlib":
		cmdStdlib(args)
	case "fetchurl":
		cmdFetchurl(args)
	case "prune":
		cmdPrune(args)
	case "log":
		cmdLog(args)
	default:
		fmt.Fprintf(os.Stderr, "direnv: unknown command: %s\n", command)
		os.Exit(1)
	}
}

func printHelp() {
	fmt.Printf(`direnv v%s
Usage: direnv COMMAND [...ARGS]

Available commands
------------------
allow [PATH_TO_RC]:
  aliases: permit, grant
  Grants direnv permission to load the given .envrc or .env file.
block [PATH_TO_RC]:
  aliases: deny, disallow, revoke
  Revokes the authorization of a given .envrc or .env file.
edit [PATH_TO_RC]:
  Opens PATH_TO_RC or the current .envrc or .env into an $EDITOR and allow
  the file to be loaded afterwards.
exec DIR COMMAND [...ARGS]:
  Executes a command after loading the first .envrc or .env found in DIR
export SHELL:
  Loads an .envrc or .env and prints the diff in terms of exports.
  Supported SHELL values are: [systemd, fish, gha, murex, tcsh, vim, zsh, pwsh, bash, elvish, gzenv, json]
fetchurl <url> [<integrity-hash>]:
  Fetches a given URL into direnv's CAS
help [SHOW_PRIVATE]:
  Shows this help
hook SHELL:
  Used to setup the shell hook
prune:
  Removes old allowed and required files
reload:
  Triggers an env reload
status [--json]:
  Prints some debug status information
stdlib:
  Displays the stdlib available in the .envrc execution context
version [VERSION_AT_LEAST]:
  prints the version or checks that direnv is older than VERSION_AT_LEAST.
log [--status | --error] <message>:
  Logs a given message
`, Version)
}

func cmdVersion(args []string) {
	if len(args) == 0 {
		fmt.Println(Version)
	} else {
		// Check if current version is at least the specified version
		requiredVersion := args[0]
		if compareVersions(Version, requiredVersion) >= 0 {
			os.Exit(0)
		} else {
			os.Exit(1)
		}
	}
}

func cmdHelp(args []string) {
	printHelp()
}

func cmdHook(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "direnv: hook: missing shell argument\n")
		os.Exit(1)
	}

	shell := args[0]

	switch shell {
	case "bash":
		fmt.Print(hookBash(execPath))
	case "zsh":
		fmt.Print(hookZsh(execPath))
	case "fish":
		fmt.Print(hookFish(execPath))
	case "tcsh":
		fmt.Print(hookTcsh(execPath))
	case "elvish":
		fmt.Print(hookElvish(execPath))
	case "pwsh":
		fmt.Print(hookPwsh(execPath))
	default:
		fmt.Fprintf(os.Stderr, "direnv: hook: unsupported shell: %s\n", shell)
		os.Exit(1)
	}
}

func cmdExport(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "direnv: export: missing shell argument\n")
		os.Exit(1)
	}

	shell := args[0]
	cwd, err := os.Getwd()
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: export: cannot get current directory: %v\n", err)
		os.Exit(1)
	}

	// Find .envrc
	rcPath, err := FindEnvrc(cwd)
	if err != nil {
		// Print empty exports if no .envrc found
		printEmptyExport(shell)
		return
	}

	// Check if allowed
	allowed, err := config.IsAllowedAndValid(rcPath)
	if err != nil {
		// Check if just allowed (even if modified)
		allowed = config.IsAllowed(rcPath)
	}

	if !allowed && !config.IsWhitelisted(rcPath) {
		// Print error and empty exports
		fmt.Fprintf(os.Stderr, "[31mdirenv: error %s is blocked. Run `direnv allow` to approve its content[0m\n", rcPath)
		printEmptyExport(shell)
		return
	}

	// Load environment
	fmt.Fprintf(os.Stderr, "[0mdirenv: loading %s\n", rcPath)
	newEnv, err := LoadEnv(rcPath, config.BashPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[31mdirenv: error loading %s: %v[0m\n", rcPath, err)
		printEmptyExport(shell)
		return
	}

	// Get current environment
	oldEnv := GetCurrentEnv()

	// Compute diff
	added, removed, changed := ComputeDiff(oldEnv, newEnv)

	// Print what was added/changed/removed
	printDiffInfo(added, changed, removed)

	// Export
	var output string
	switch shell {
	case "bash", "zsh":
		output = ExportBash(added, changed, removed)
	case "fish":
		output = ExportFish(added, changed, removed)
	case "json":
		output, _ = ExportJSON(added, changed, removed)
	case "pwsh":
		output = ExportPwsh(added, changed, removed)
	case "tcsh":
		output = ExportTcsh(added, changed, removed)
	case "elvish":
		output = ExportElvish(added, changed, removed)
	case "gha":
		output = ExportGHA(added, changed, removed)
	default:
		fmt.Fprintf(os.Stderr, "direnv: export: unsupported shell: %s\n", shell)
		os.Exit(1)
	}

	// Add direnv metadata
	output = addMetadata(output, rcPath, shell)
	fmt.Print(output)
}

func cmdAllow(args []string) {
	rcPath := ".envrc"
	if len(args) > 0 {
		rcPath = args[0]
	}

	if rcPath == "." {
		rcPath = ".envrc"
	}

	// Make absolute
	absPath, err := filepath.Abs(rcPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: error: %v\n", err)
		os.Exit(1)
	}

	if err := config.Allow(absPath); err != nil {
		fmt.Fprintf(os.Stderr, "direnv: error: %v\n", err)
		os.Exit(1)
	}

	fmt.Fprintf(os.Stderr, "[0mdirenv: loading %s\n", absPath)
}

func cmdBlock(args []string) {
	rcPath := ".envrc"
	if len(args) > 0 {
		rcPath = args[0]
	}

	if rcPath == "." {
		rcPath = ".envrc"
	}

	// Make absolute
	absPath, err := filepath.Abs(rcPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: error: %v\n", err)
		os.Exit(1)
	}

	if err := config.Block(absPath); err != nil {
		fmt.Fprintf(os.Stderr, "direnv: error: %v\n", err)
		os.Exit(1)
	}
}

func cmdStatus(args []string) {
	jsonOutput := false
	for _, arg := range args {
		if arg == "--json" {
			jsonOutput = true
		}
	}

	if jsonOutput {
		status := map[string]interface{}{
			"config": map[string]string{
				"ConfigDir": config.ConfigDir,
				"SelfPath":  config.SelfPath,
			},
			"state": map[string]interface{}{
				"foundRC": nil,
				"loadedRC": nil,
			},
		}

		cwd, _ := os.Getwd()
		rcPath, err := FindEnvrc(cwd)
		if err == nil {
			status["state"].(map[string]interface{})["foundRC"] = rcPath
			if config.IsAllowed(rcPath) {
				status["state"].(map[string]interface{})["loadedRC"] = rcPath
			}
		}

		data, _ := json.MarshalIndent(status, "", "  ")
		fmt.Println(string(data))
	} else {
		fmt.Printf("direnv exec path %s\n", execPath)
		fmt.Printf("DIRENV_CONFIG %s\n", config.ConfigDir)
		fmt.Printf("bash_path %s\n", config.BashPath)
		fmt.Printf("disable_stdin false\n")
		fmt.Printf("warn_timeout 5s\n")
		fmt.Printf("whitelist.prefix []\n")
		fmt.Printf("whitelist.exact map[]\n")

		cwd, _ := os.Getwd()
		rcPath, err := FindEnvrc(cwd)
		if err == nil && config.IsAllowed(rcPath) {
			fmt.Printf("Loaded .envrc from %s\n", rcPath)
		} else {
			fmt.Printf("No .envrc or .env loaded\n")
		}

		if err != nil {
			fmt.Printf("No .envrc or .env found\n")
		} else {
			fmt.Printf(".envrc found at %s\n", rcPath)
		}
	}
}

func cmdExec(args []string) {
	if len(args) < 2 {
		fmt.Fprintf(os.Stderr, "direnv: exec: missing DIR or COMMAND argument\n")
		os.Exit(1)
	}

	dir := args[0]
	command := args[1:]

	// Find .envrc in dir
	rcPath, err := FindEnvrc(dir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: exec: no .envrc or .env found in %s\n", dir)
		os.Exit(1)
	}

	// Check if allowed
	allowed, _ := config.IsAllowedAndValid(rcPath)
	if !allowed && !config.IsAllowed(rcPath) {
		fmt.Fprintf(os.Stderr, "direnv: exec: %s is not allowed\n", rcPath)
		os.Exit(1)
	}

	fmt.Fprintf(os.Stderr, "[0mdirenv: loading %s\n", rcPath)

	// Load environment
	newEnv, err := LoadEnv(rcPath, config.BashPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: exec: error loading %s: %v\n", rcPath, err)
		os.Exit(1)
	}

	// Merge with current environment
	env := os.Environ()
	for k, v := range newEnv {
		env = append(env, k+"="+v)
	}

	// Execute command
	cmd := exec.Command(command[0], command[1:]...)
	cmd.Env = env
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	err = cmd.Run()
	if err != nil {
		os.Exit(1)
	}
}

func cmdEdit(args []string) {
	rcPath := ".envrc"
	if len(args) > 0 {
		rcPath = args[0]
	}

	if rcPath == "." {
		rcPath = ".envrc"
	}

	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = "vim"
	}

	// Open in editor
	cmd := exec.Command(editor, rcPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()

	// Allow the file
	absPath, _ := filepath.Abs(rcPath)
	config.Allow(absPath)
}

func cmdReload(args []string) {
	// Stub
}

func cmdStdlib(args []string) {
	fmt.Print(getStdlib())
}

func cmdFetchurl(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "[31mdirenv: error missing URL argument[0m\n")
		os.Exit(1)
	}

	// Stub - not implementing full fetchurl
	fmt.Fprintf(os.Stderr, "direnv: fetchurl not yet implemented\n")
	os.Exit(1)
}

func cmdPrune(args []string) {
	// Stub
}

func cmdLog(args []string) {
	// Stub
	for _, arg := range args {
		fmt.Println(arg)
	}
}

func compareVersions(v1, v2 string) int {
	// Simple version comparison - parse semver
	// TODO: implement proper version comparison
	if v1 == v2 {
		return 0
	}
	if v1 > v2 {
		return 1
	}
	return -1
}

func printEmptyExport(shell string) {
	// Print direnv metadata even without loading
	switch shell {
	case "bash", "zsh":
		fmt.Printf("export DIRENV_DIR=$'-';")
	case "json":
		fmt.Printf("{}")
	}
}

func printDiffInfo(added, changed, removed map[string]string) {
	for k := range added {
		fmt.Fprintf(os.Stderr, "[0mdirenv: export +%s\n", k)
	}
	for k := range changed {
		fmt.Fprintf(os.Stderr, "[0mdirenv: export ~%s\n", k)
	}
	for k := range removed {
		fmt.Fprintf(os.Stderr, "[0mdirenv: export -%s\n", k)
	}
}

func addMetadata(output, rcPath, shell string) string {
	// Add direnv metadata at the end
	direnvDir := filepath.Dir(rcPath)
	if direnvDir == "." {
		direnvDir = "-"
	} else if !filepath.IsAbs(direnvDir) {
		abs, _ := filepath.Abs(direnvDir)
		direnvDir = "-" + abs
	}

	// Create watches data (compressed)
	watches := createWatches(rcPath)

	// Create diff data (compressed)
	diff := createDiff()

	switch shell {
	case "bash", "zsh":
		return fmt.Sprintf(
			"export DIRENV_FILE=%q;export DIRENV_WATCHES=%q;export DIRENV_DIFF=%q;export DIRENV_DIR=%q;%s",
			rcPath,
			watches,
			diff,
			direnvDir,
			output,
		)
	default:
		return output
	}
}

func createWatches(rcPath string) string {
	// Create a simple compressed representation
	data := []byte(`{"version": 1, "files": ["` + rcPath + `"]}`)
	return encodeGzipped(data)
}

func createDiff() string {
	data := []byte(`{"changes": []}`)
	return encodeGzipped(data)
}

func encodeGzipped(data []byte) string {
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	gz.Write(data)
	gz.Close()

	return "'" + base64.StdEncoding.EncodeToString(buf.Bytes()) + "'"
}

// Stub implementations for export functions
func ExportPwsh(added, changed, removed map[string]string) string {
	var buf bytes.Buffer
	for k, v := range added {
		buf.WriteString(fmt.Sprintf("$Env:%s = %q\n", k, v))
	}
	for k, v := range changed {
		buf.WriteString(fmt.Sprintf("$Env:%s = %q\n", k, v))
	}
	for k := range removed {
		buf.WriteString(fmt.Sprintf("Remove-Item Env:%s\n", k))
	}
	return buf.String()
}

func ExportTcsh(added, changed, removed map[string]string) string {
	var buf bytes.Buffer
	for k, v := range added {
		buf.WriteString(fmt.Sprintf("setenv %s %q\n", k, v))
	}
	for k, v := range changed {
		buf.WriteString(fmt.Sprintf("setenv %s %q\n", k, v))
	}
	for k := range removed {
		buf.WriteString(fmt.Sprintf("unsetenv %s\n", k))
	}
	return buf.String()
}

func ExportElvish(added, changed, removed map[string]string) string {
	var buf bytes.Buffer
	for k, v := range added {
		buf.WriteString(fmt.Sprintf("set-env %s %q\n", k, v))
	}
	for k, v := range changed {
		buf.WriteString(fmt.Sprintf("set-env %s %q\n", k, v))
	}
	for k := range removed {
		buf.WriteString(fmt.Sprintf("del-env %s\n", k))
	}
	return buf.String()
}

func ExportGHA(added, changed, removed map[string]string) string {
	var buf bytes.Buffer
	for k, v := range added {
		buf.WriteString(fmt.Sprintf("echo \"%s=%s\" >> $GITHUB_ENV\n", k, v))
	}
	for k, v := range changed {
		buf.WriteString(fmt.Sprintf("echo \"%s=%s\" >> $GITHUB_ENV\n", k, v))
	}
	return buf.String()
}
