}

func main() {
	if len(os.Args) < 2 {
		printHelp()
		os.Exit(1)
	}

	command := os.Args[1]
	args := os.Args[2:]

	switch command {
	case "version":
		cmdVersion(args)
	case "help":
		cmdHelp(args)
	case "hook":
		cmdHook(args)
	case "export":
		cmdExport(args)
	case "allow", "permit", "grant":
		cmdAllow(args)
	case "block", "deny", "disallow", "revoke":
		cmdBlock(args)
	case "status":
		cmdStatus(args)
	case "exec":
		cmdExec(args)
