package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
)

var ignoredVars = map[string]bool{
	"DIRENV_IN_ENVRC": true,
}

// LoadEnv loads an .envrc file and returns the environment variables it sets
func LoadEnv(rcPath string, bashPath string) (map[string]string, error) {
	// Create a bash script that sources the stdlib and the .envrc
	// We use absolute paths for env and sort to avoid PATH issues
	script := fmt.Sprintf(`
#!/usr/bin/env bash
set -e

# Source the stdlib first
%s

# Now source the .envrc
cd "%s"
source "%s"

# Dump all environment variables using absolute paths
/usr/bin/env | /usr/bin/sort
`, getStdlib(), filepath.Dir(rcPath), rcPath)

	// Run the script in bash and capture the output
	cmd := exec.Command(bashPath, "-c", script)
	cmd.Env = os.Environ()
	cmd.Stdin = nil // Disable stdin

	output, err := cmd.Output()
	if err != nil {
		// The script may have failed, but we might still get some output
		if exitErr, ok := err.(*exec.ExitError); ok {
			// Print stderr if available
			if len(exitErr.Stderr) > 0 {
				fmt.Fprintf(os.Stderr, "[31mdirenv: error %s[0m\n", string(exitErr.Stderr))
			}
		}
		return nil, err
	}

	// Parse the output into an environment map
	envMap := make(map[string]string)
	for _, line := range strings.Split(string(output), "\n") {
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) == 2 {
			envMap[parts[0]] = parts[1]
		}
	}

	return envMap, nil
}

// ComputeDiff computes the difference between the new and old environment
func ComputeDiff(oldEnv, newEnv map[string]string) (added, removed, changed map[string]string) {
	added = make(map[string]string)
	removed = make(map[string]string)
	changed = make(map[string]string)

	// Find added and changed variables
	for k, v := range newEnv {
		if ignoredVars[k] {
			continue
		}
		if oldVal, exists := oldEnv[k]; !exists {
			added[k] = v
		} else if oldVal != v {
			changed[k] = v
		}
	}

	// Find removed variables
	for k, v := range oldEnv {
		if ignoredVars[k] {
			continue
		}
		if _, exists := newEnv[k]; !exists {
			removed[k] = v
		}
	}

	return
}

// ExportBash exports environment variables in bash format
func ExportBash(added, changed, removed map[string]string) string {
	var buf bytes.Buffer

	// Export added and changed variables
	for k, v := range added {
		buf.WriteString(fmt.Sprintf("export %s=%q;", k, v))
	}
	for k, v := range changed {
		buf.WriteString(fmt.Sprintf("export %s=%q;", k, v))
	}

	// Unset removed variables
	for k := range removed {
		buf.WriteString(fmt.Sprintf("unset %s;", k))
	}

	return buf.String()
}

// ExportJSON exports environment variables in JSON format
func ExportJSON(added, changed, removed map[string]string) (string, error) {
	result := make(map[string]interface{})
	result["+"] = added
	result["~"] = changed
	result["-"] = removed

	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return "", err
	}

	return string(data), nil
}

// ExportFish exports environment variables in fish format
func ExportFish(added, changed, removed map[string]string) string {
	var buf bytes.Buffer

	// Export added and changed variables
	for k, v := range added {
		buf.WriteString(fmt.Sprintf("set -gx %s %s\n", k, v))
	}
	for k, v := range changed {
		buf.WriteString(fmt.Sprintf("set -gx %s %s\n", k, v))
	}

	// Unset removed variables
	for k := range removed {
		buf.WriteString(fmt.Sprintf("set -e %s\n", k))
	}

	return buf.String()
}

// ExportZsh exports environment variables in zsh format (same as bash)
func ExportZsh(added, changed, removed map[string]string) string {
	return ExportBash(added, changed, removed)
}

// GetCurrentEnv returns the current environment as a map
func GetCurrentEnv() map[string]string {
	env := make(map[string]string)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		}
	}
	return env
}

// Export exports the environment in the specified shell format
func Export(rcPath string, shell string, bashPath string) (string, error) {
	// Load the environment from the .envrc
	newEnv, err := LoadEnv(rcPath, bashPath)
	if err != nil {
		return "", err
	}

	// Get the current environment (before loading .envrc)
	oldEnv := GetCurrentEnv()

	// Compute the diff
	added, removed, changed := ComputeDiff(oldEnv, newEnv)

	// Export based on the shell type
	switch shell {
	case "bash", "zsh":
		return ExportBash(added, changed, removed), nil
	case "fish":
		return ExportFish(added, changed, removed), nil
	case "json":
		return ExportJSON(added, changed, removed)
	case "tcsh":
		// TODO: implement tcsh export
		return "", fmt.Errorf("tcsh export not yet implemented")
	default:
		return "", fmt.Errorf("unsupported shell: %s", shell)
	}
}

// SortedKeys returns the sorted keys of a map
func SortedKeys(m map[string]string) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
EOF

